import math
def solve(a,b):
    if len(a) != len(b):
        return None
    norm = math.sqrt(sum(x*x for x in a)*sum(y*y for y in b))
    if norm == 0:
        return 0
    return round(sum(x*y for x,y in zip(a,b))/norm,6)

