from functools import lru_cache
def solve(values):
    calls=0
    @lru_cache(maxsize=None)
    def embed(x):
        nonlocal calls
        calls+=1
        return x*x
    results=[embed(x) for x in values]
    return {'results':results,'computations':calls}

